const PR64=[{label:"Ví dụ: Leo từng bước",input:"9\n1 2\n1 3\n2 4\n2 5\n3 6\n5 7\n5 8\n6 9\n",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint n, LOG;\nvector<vector<int>> adj;\nvector<int> cha, sau;\n\nvoid bfs(int goc) {                    // cha và độ sâu của mọi đỉnh\n    cha.assign(n + 1, 0);\n    sau.assign(n + 1, -1);\n    vector<int> q;\n    q.push_back(goc);\n    cha[goc] = goc;                    // gốc lấy chính nó làm cha\n    sau[goc] = 0;\n    for (int i = 0; i < (int)q.size(); i++) {\n        int u = q[i];\n        for (int v : adj[u])\n            if (sau[v] == -1) { sau[v] = sau[u] + 1; cha[v] = u; q.push_back(v); }\n    }\n}\n\nvoid docCay() {\n    cin >> n;\n    adj.resize(n + 1);\n    for (int i = 0; i < n - 1; i++) {\n        int a, b;\n        cin >> a >> b;\n        adj[a].push_back(b);\n        adj[b].push_back(a);\n    }\n}\n\nint lcaCham(int u, int v) {\n    while (sau[u] > sau[v]) u = cha[u];   // đưa về cùng độ sâu\n    while (sau[v] > sau[u]) v = cha[v];\n    while (u != v) { u = cha[u]; v = cha[v]; }\n    return u;\n}\n\nint main() {\n    docCay();\n    bfs(1);\n    cout << lcaCham(7, 4) << \" \" << lcaCham(7, 9) << \" \" << lcaCham(8, 5) << \"\\n\";\n    return 0;\n}",viz:[{type:"graph",base:1,xy:[[0.5,0],[0.25,0.33],[0.75,0.33],[0.08,0.66],[0.4,0.66],[0.75,0.66],[0.28,1],[0.52,1],[0.75,1]],adj:"adj",par:"cha",lab:"sau",cur:["u","v"]}],py:{code:"def doc_cay():\n    n = int(input())\n    adj = [[] for _ in range(n + 1)]\n    for _ in range(n - 1):\n        a, b = map(int, input().split())\n        adj[a].append(b)\n        adj[b].append(a)\n    return n, adj\n\ndef bfs(goc):                          # cha và độ sâu của mọi đỉnh\n    cha = [0] * (n + 1)\n    sau = [-1] * (n + 1)\n    cha[goc] = goc                     # gốc lấy chính nó làm cha\n    sau[goc] = 0\n    q = [goc]\n    for u in q:\n        for v in adj[u]:\n            if sau[v] == -1:\n                sau[v] = sau[u] + 1\n                cha[v] = u\n                q.append(v)\n    return cha, sau\n\ndef lca_cham(u, v):\n    while sau[u] > sau[v]:             # đưa về cùng độ sâu\n        u = cha[u]\n    while sau[v] > sau[u]:\n        v = cha[v]\n    while u != v:\n        u = cha[u]\n        v = cha[v]\n    return u\n\nn, adj = doc_cay()\ncha, sau = bfs(1)\nprint(lca_cham(7, 4), lca_cham(7, 9), lca_cham(8, 5))"},cs:{code:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static int n;\n    static List<int>[] adj;\n    static int[] cha, sau;\n\n    static void DocCay()\n    {\n        n = int.Parse(Console.ReadLine());\n        adj = new List<int>[n + 1];\n        for (int i = 0; i <= n; i++) adj[i] = new List<int>();\n        for (int i = 0; i < n - 1; i++)\n        {\n            int[] e = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            adj[e[0]].Add(e[1]);\n            adj[e[1]].Add(e[0]);\n        }\n    }\n\n    static void Bfs(int goc)               // cha và độ sâu của mọi đỉnh\n    {\n        cha = new int[n + 1];\n        sau = new int[n + 1];\n        for (int i = 0; i <= n; i++) sau[i] = -1;\n        var q = new List<int> { goc };\n        cha[goc] = goc;                    // gốc lấy chính nó làm cha\n        sau[goc] = 0;\n        for (int i = 0; i < q.Count; i++)\n        {\n            int u = q[i];\n            foreach (int v in adj[u])\n                if (sau[v] == -1) { sau[v] = sau[u] + 1; cha[v] = u; q.Add(v); }\n        }\n    }\n\n    static int LcaCham(int u, int v)\n    {\n        while (sau[u] > sau[v]) u = cha[u];   // đưa về cùng độ sâu\n        while (sau[v] > sau[u]) v = cha[v];\n        while (u != v) { u = cha[u]; v = cha[v]; }\n        return u;\n    }\n\n    static void Main()\n    {\n        DocCay();\n        Bfs(1);\n        Console.WriteLine(LcaCham(7, 4) + \" \" + LcaCham(7, 9) + \" \" + LcaCham(8, 5));\n    }\n}"}},{label:"Ví dụ: Bảng nhảy lũy thừa 2",input:"9\n1 2\n1 3\n2 4\n2 5\n3 6\n5 7\n5 8\n6 9\n",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint n, LOG;\nvector<vector<int>> adj;\nvector<int> cha, sau;\n\nvoid bfs(int goc) {                    // cha và độ sâu của mọi đỉnh\n    cha.assign(n + 1, 0);\n    sau.assign(n + 1, -1);\n    vector<int> q;\n    q.push_back(goc);\n    cha[goc] = goc;                    // gốc lấy chính nó làm cha\n    sau[goc] = 0;\n    for (int i = 0; i < (int)q.size(); i++) {\n        int u = q[i];\n        for (int v : adj[u])\n            if (sau[v] == -1) { sau[v] = sau[u] + 1; cha[v] = u; q.push_back(v); }\n    }\n}\n\nvoid docCay() {\n    cin >> n;\n    adj.resize(n + 1);\n    for (int i = 0; i < n - 1; i++) {\n        int a, b;\n        cin >> a >> b;\n        adj[a].push_back(b);\n        adj[b].push_back(a);\n    }\n}\n\nvector<vector<int>> up;\n\nvoid dungBang() {\n    LOG = 1;\n    while ((1 << LOG) <= n) LOG++;\n    up.assign(LOG, vector<int>(n + 1));\n    for (int v = 1; v <= n; v++) up[0][v] = cha[v];\n    for (int k = 1; k < LOG; k++)\n        for (int v = 1; v <= n; v++)\n            up[k][v] = up[k - 1][up[k - 1][v]];   // 2^k = 2^(k-1) + 2^(k-1)\n}\n\nint main() {\n    docCay();\n    bfs(1);\n    dungBang();\n    for (int v = 7; v <= 9; v++) {\n        cout << v << \":\";\n        for (int k = 0; k < LOG; k++) cout << \" \" << up[k][v];\n        cout << \"\\n\";\n    }\n    return 0;\n}",viz:[{type:"graph",base:1,xy:[[0.5,0],[0.25,0.33],[0.75,0.33],[0.08,0.66],[0.4,0.66],[0.75,0.66],[0.28,1],[0.52,1],[0.75,1]],adj:"adj",par:"cha",lab:"sau",cur:["v"]},{type:"vars",names:["v","k","LOG"]}],py:{code:"def doc_cay():\n    n = int(input())\n    adj = [[] for _ in range(n + 1)]\n    for _ in range(n - 1):\n        a, b = map(int, input().split())\n        adj[a].append(b)\n        adj[b].append(a)\n    return n, adj\n\ndef bfs(goc):                          # cha và độ sâu của mọi đỉnh\n    cha = [0] * (n + 1)\n    sau = [-1] * (n + 1)\n    cha[goc] = goc                     # gốc lấy chính nó làm cha\n    sau[goc] = 0\n    q = [goc]\n    for u in q:\n        for v in adj[u]:\n            if sau[v] == -1:\n                sau[v] = sau[u] + 1\n                cha[v] = u\n                q.append(v)\n    return cha, sau\n\ndef dung_bang():\n    LOG = n.bit_length()               # 2^LOG > n\n    up = [cha[:]]\n    for k in range(1, LOG):\n        prev = up[k - 1]\n        up.append([prev[prev[v]] for v in range(n + 1)])   # 2^k = 2^(k-1) + 2^(k-1)\n    return LOG, up\n\nn, adj = doc_cay()\ncha, sau = bfs(1)\nLOG, up = dung_bang()\nfor v in range(7, 10):\n    print(str(v) + \":\", *[up[k][v] for k in range(LOG)])"},cs:{code:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static int n;\n    static List<int>[] adj;\n    static int[] cha, sau;\n\n    static void DocCay()\n    {\n        n = int.Parse(Console.ReadLine());\n        adj = new List<int>[n + 1];\n        for (int i = 0; i <= n; i++) adj[i] = new List<int>();\n        for (int i = 0; i < n - 1; i++)\n        {\n            int[] e = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            adj[e[0]].Add(e[1]);\n            adj[e[1]].Add(e[0]);\n        }\n    }\n\n    static void Bfs(int goc)               // cha và độ sâu của mọi đỉnh\n    {\n        cha = new int[n + 1];\n        sau = new int[n + 1];\n        for (int i = 0; i <= n; i++) sau[i] = -1;\n        var q = new List<int> { goc };\n        cha[goc] = goc;                    // gốc lấy chính nó làm cha\n        sau[goc] = 0;\n        for (int i = 0; i < q.Count; i++)\n        {\n            int u = q[i];\n            foreach (int v in adj[u])\n                if (sau[v] == -1) { sau[v] = sau[u] + 1; cha[v] = u; q.Add(v); }\n        }\n    }\n\n    static int LOG;\n    static int[][] up;\n\n    static void DungBang()\n    {\n        LOG = 1;\n        while ((1 << LOG) <= n) LOG++;\n        up = new int[LOG][];\n        up[0] = (int[])cha.Clone();\n        for (int k = 1; k < LOG; k++)\n        {\n            up[k] = new int[n + 1];\n            for (int v = 0; v <= n; v++) up[k][v] = up[k - 1][up[k - 1][v]];   // 2^k = 2^(k-1) + 2^(k-1)\n        }\n    }\n\n    static void Main()\n    {\n        DocCay();\n        Bfs(1);\n        DungBang();\n        for (int v = 7; v <= 9; v++)\n        {\n            Console.Write(v + \":\");\n            for (int k = 0; k < LOG; k++) Console.Write(\" \" + up[k][v]);\n            Console.WriteLine();\n        }\n    }\n}"}},{label:"Ví dụ: LCA bằng nhảy nhị phân",input:"9\n1 2\n1 3\n2 4\n2 5\n3 6\n5 7\n5 8\n6 9\n",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint n, LOG;\nvector<vector<int>> adj;\nvector<int> cha, sau;\n\nvoid bfs(int goc) {                    // cha và độ sâu của mọi đỉnh\n    cha.assign(n + 1, 0);\n    sau.assign(n + 1, -1);\n    vector<int> q;\n    q.push_back(goc);\n    cha[goc] = goc;                    // gốc lấy chính nó làm cha\n    sau[goc] = 0;\n    for (int i = 0; i < (int)q.size(); i++) {\n        int u = q[i];\n        for (int v : adj[u])\n            if (sau[v] == -1) { sau[v] = sau[u] + 1; cha[v] = u; q.push_back(v); }\n    }\n}\n\nvoid docCay() {\n    cin >> n;\n    adj.resize(n + 1);\n    for (int i = 0; i < n - 1; i++) {\n        int a, b;\n        cin >> a >> b;\n        adj[a].push_back(b);\n        adj[b].push_back(a);\n    }\n}\n\nvector<vector<int>> up;\n\nvoid dungBang() {\n    LOG = 1;\n    while ((1 << LOG) <= n) LOG++;\n    up.assign(LOG, vector<int>(n + 1));\n    for (int v = 1; v <= n; v++) up[0][v] = cha[v];\n    for (int k = 1; k < LOG; k++)\n        for (int v = 1; v <= n; v++)\n            up[k][v] = up[k - 1][up[k - 1][v]];   // 2^k = 2^(k-1) + 2^(k-1)\n}\n\nint lca(int u, int v) {\n    if (sau[u] < sau[v]) swap(u, v);\n    int d = sau[u] - sau[v];\n    for (int k = 0; k < LOG; k++)\n        if (d >> k & 1) u = up[k][u];  // đưa u lên cùng độ sâu với v\n    if (u == v) return u;\n    for (int k = LOG - 1; k >= 0; k--)\n        if (up[k][u] != up[k][v]) { u = up[k][u]; v = up[k][v]; }\n    return up[0][u];\n}\n\nint main() {\n    docCay();\n    bfs(1);\n    dungBang();\n    cout << lca(7, 4) << \" \" << lca(7, 9) << \" \" << lca(8, 5) << \" \" << lca(7, 8) << \"\\n\";\n    return 0;\n}",viz:[{type:"graph",base:1,xy:[[0.5,0],[0.25,0.33],[0.75,0.33],[0.08,0.66],[0.4,0.66],[0.75,0.66],[0.28,1],[0.52,1],[0.75,1]],adj:"adj",par:"cha",lab:"sau",cur:["u","v"]},{type:"vars",names:["u","v","d","k"]}],py:{code:"def doc_cay():\n    n = int(input())\n    adj = [[] for _ in range(n + 1)]\n    for _ in range(n - 1):\n        a, b = map(int, input().split())\n        adj[a].append(b)\n        adj[b].append(a)\n    return n, adj\n\ndef bfs(goc):                          # cha và độ sâu của mọi đỉnh\n    cha = [0] * (n + 1)\n    sau = [-1] * (n + 1)\n    cha[goc] = goc                     # gốc lấy chính nó làm cha\n    sau[goc] = 0\n    q = [goc]\n    for u in q:\n        for v in adj[u]:\n            if sau[v] == -1:\n                sau[v] = sau[u] + 1\n                cha[v] = u\n                q.append(v)\n    return cha, sau\n\ndef dung_bang():\n    LOG = n.bit_length()               # 2^LOG > n\n    up = [cha[:]]\n    for k in range(1, LOG):\n        prev = up[k - 1]\n        up.append([prev[prev[v]] for v in range(n + 1)])   # 2^k = 2^(k-1) + 2^(k-1)\n    return LOG, up\n\ndef lca(u, v):\n    if sau[u] < sau[v]:\n        u, v = v, u\n    d = sau[u] - sau[v]\n    for k in range(LOG):\n        if d >> k & 1:\n            u = up[k][u]               # đưa u lên cùng độ sâu với v\n    if u == v:\n        return u\n    for k in range(LOG - 1, -1, -1):\n        if up[k][u] != up[k][v]:\n            u = up[k][u]\n            v = up[k][v]\n    return up[0][u]\n\nn, adj = doc_cay()\ncha, sau = bfs(1)\nLOG, up = dung_bang()\nprint(lca(7, 4), lca(7, 9), lca(8, 5), lca(7, 8))"},cs:{code:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static int n;\n    static List<int>[] adj;\n    static int[] cha, sau;\n\n    static void DocCay()\n    {\n        n = int.Parse(Console.ReadLine());\n        adj = new List<int>[n + 1];\n        for (int i = 0; i <= n; i++) adj[i] = new List<int>();\n        for (int i = 0; i < n - 1; i++)\n        {\n            int[] e = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            adj[e[0]].Add(e[1]);\n            adj[e[1]].Add(e[0]);\n        }\n    }\n\n    static void Bfs(int goc)               // cha và độ sâu của mọi đỉnh\n    {\n        cha = new int[n + 1];\n        sau = new int[n + 1];\n        for (int i = 0; i <= n; i++) sau[i] = -1;\n        var q = new List<int> { goc };\n        cha[goc] = goc;                    // gốc lấy chính nó làm cha\n        sau[goc] = 0;\n        for (int i = 0; i < q.Count; i++)\n        {\n            int u = q[i];\n            foreach (int v in adj[u])\n                if (sau[v] == -1) { sau[v] = sau[u] + 1; cha[v] = u; q.Add(v); }\n        }\n    }\n\n    static int LOG;\n    static int[][] up;\n\n    static void DungBang()\n    {\n        LOG = 1;\n        while ((1 << LOG) <= n) LOG++;\n        up = new int[LOG][];\n        up[0] = (int[])cha.Clone();\n        for (int k = 1; k < LOG; k++)\n        {\n            up[k] = new int[n + 1];\n            for (int v = 0; v <= n; v++) up[k][v] = up[k - 1][up[k - 1][v]];   // 2^k = 2^(k-1) + 2^(k-1)\n        }\n    }\n\n    static int Lca(int u, int v)\n    {\n        if (sau[u] < sau[v]) { int tg = u; u = v; v = tg; }\n        int d = sau[u] - sau[v];\n        for (int k = 0; k < LOG; k++)\n            if ((d >> k & 1) == 1) u = up[k][u];   // đưa u lên cùng độ sâu với v\n        if (u == v) return u;\n        for (int k = LOG - 1; k >= 0; k--)\n            if (up[k][u] != up[k][v]) { u = up[k][u]; v = up[k][v]; }\n        return up[0][u];\n    }\n\n    static void Main()\n    {\n        DocCay();\n        Bfs(1);\n        DungBang();\n        Console.WriteLine(Lca(7, 4) + \" \" + Lca(7, 9) + \" \" + Lca(8, 5) + \" \" + Lca(7, 8));\n    }\n}"}},{label:"Ví dụ: Khoảng cách giữa hai đỉnh",input:"6\n1 2 3\n1 3 4\n2 4 2\n2 5 7\n3 6 1\n",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint n, LOG;\nvector<vector<pair<int, int>>> adj;    // (đỉnh kề, độ dài cạnh)\nvector<int> cha, sau;\nvector<long long> d;                   // khoảng cách từ gốc\nvector<vector<int>> up;\n\nint main() {\n    cin >> n;\n    adj.resize(n + 1);\n    for (int i = 0; i < n - 1; i++) {\n        int a, b, w;\n        cin >> a >> b >> w;\n        adj[a].push_back({b, w});\n        adj[b].push_back({a, w});\n    }\n    cha.assign(n + 1, 0); sau.assign(n + 1, -1); d.assign(n + 1, 0);\n    vector<int> q = {1};\n    cha[1] = 1; sau[1] = 0;\n    for (int i = 0; i < (int)q.size(); i++) {\n        int u = q[i];\n        for (auto [v, w] : adj[u])\n            if (sau[v] == -1) { sau[v] = sau[u] + 1; d[v] = d[u] + w; cha[v] = u; q.push_back(v); }\n    }\n    LOG = 1;\n    while ((1 << LOG) <= n) LOG++;\n    up.assign(LOG, vector<int>(n + 1));\n    for (int v = 1; v <= n; v++) up[0][v] = cha[v];\n    for (int k = 1; k < LOG; k++)\n        for (int v = 1; v <= n; v++) up[k][v] = up[k - 1][up[k - 1][v]];\n    int u = 4, v = 6;\n    int a = u, b = v;                  // tìm LCA của a, b\n    if (sau[a] < sau[b]) swap(a, b);\n    for (int k = 0; k < LOG; k++) if ((sau[a] - sau[b]) >> k & 1) a = up[k][a];\n    if (a != b) {\n        for (int k = LOG - 1; k >= 0; k--)\n            if (up[k][a] != up[k][b]) { a = up[k][a]; b = up[k][b]; }\n        a = up[0][a];\n    }\n    cout << \"lca = \" << a << \", khoang cach = \" << d[u] + d[v] - 2 * d[a] << \"\\n\";\n    return 0;\n}",viz:[{type:"graph",adj:"adj",base:1,par:"cha",lab:"d",cur:["u","v"]},{type:"vars",names:["a","b","k"]}],py:{code:"n = int(input())\nadj = [[] for _ in range(n + 1)]       # (đỉnh kề, độ dài cạnh)\nfor _ in range(n - 1):\n    a, b, w = map(int, input().split())\n    adj[a].append((b, w))\n    adj[b].append((a, w))\ncha = [0] * (n + 1)\nsau = [-1] * (n + 1)\nd = [0] * (n + 1)                      # khoảng cách từ gốc\ncha[1] = 1\nsau[1] = 0\nq = [1]\nfor u in q:\n    for v, w in adj[u]:\n        if sau[v] == -1:\n            sau[v] = sau[u] + 1\n            d[v] = d[u] + w\n            cha[v] = u\n            q.append(v)\n\ndef dung_bang():\n    LOG = n.bit_length()               # 2^LOG > n\n    up = [cha[:]]\n    for k in range(1, LOG):\n        prev = up[k - 1]\n        up.append([prev[prev[v]] for v in range(n + 1)])   # 2^k = 2^(k-1) + 2^(k-1)\n    return LOG, up\n\ndef lca(u, v):\n    if sau[u] < sau[v]:\n        u, v = v, u\n    d = sau[u] - sau[v]\n    for k in range(LOG):\n        if d >> k & 1:\n            u = up[k][u]               # đưa u lên cùng độ sâu với v\n    if u == v:\n        return u\n    for k in range(LOG - 1, -1, -1):\n        if up[k][u] != up[k][v]:\n            u = up[k][u]\n            v = up[k][v]\n    return up[0][u]\n\nLOG, up = dung_bang()\nu, v = 4, 6\na = lca(u, v)\nprint(\"lca = \" + str(a) + \", khoang cach = \" + str(d[u] + d[v] - 2 * d[a]))"},cs:{code:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static int n;\n    static int[] cha, sau;\n\n    static int LOG;\n    static int[][] up;\n\n    static void DungBang()\n    {\n        LOG = 1;\n        while ((1 << LOG) <= n) LOG++;\n        up = new int[LOG][];\n        up[0] = (int[])cha.Clone();\n        for (int k = 1; k < LOG; k++)\n        {\n            up[k] = new int[n + 1];\n            for (int v = 0; v <= n; v++) up[k][v] = up[k - 1][up[k - 1][v]];   // 2^k = 2^(k-1) + 2^(k-1)\n        }\n    }\n\n    static int Lca(int u, int v)\n    {\n        if (sau[u] < sau[v]) { int tg = u; u = v; v = tg; }\n        int d = sau[u] - sau[v];\n        for (int k = 0; k < LOG; k++)\n            if ((d >> k & 1) == 1) u = up[k][u];   // đưa u lên cùng độ sâu với v\n        if (u == v) return u;\n        for (int k = LOG - 1; k >= 0; k--)\n            if (up[k][u] != up[k][v]) { u = up[k][u]; v = up[k][v]; }\n        return up[0][u];\n    }\n\n    static void Main()\n    {\n        n = int.Parse(Console.ReadLine());\n        var adj = new List<int[]>[n + 1];      // {đỉnh kề, độ dài cạnh}\n        for (int i = 0; i <= n; i++) adj[i] = new List<int[]>();\n        for (int i = 0; i < n - 1; i++)\n        {\n            int[] e = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            adj[e[0]].Add(new[] { e[1], e[2] });\n            adj[e[1]].Add(new[] { e[0], e[2] });\n        }\n        cha = new int[n + 1];\n        sau = new int[n + 1];\n        long[] d = new long[n + 1];            // khoảng cách từ gốc\n        for (int i = 0; i <= n; i++) sau[i] = -1;\n        var q = new List<int> { 1 };\n        cha[1] = 1;\n        sau[1] = 0;\n        for (int i = 0; i < q.Count; i++)\n        {\n            int u = q[i];\n            foreach (int[] e in adj[u])\n                if (sau[e[0]] == -1) { sau[e[0]] = sau[u] + 1; d[e[0]] = d[u] + e[1]; cha[e[0]] = u; q.Add(e[0]); }\n        }\n        DungBang();\n        int x = 4, y = 6;\n        int a = Lca(x, y);\n        Console.WriteLine(\"lca = \" + a + \", khoang cach = \" + (d[x] + d[y] - 2 * d[a]));\n    }\n}"}},{label:"Lỗi: quên đưa hai đỉnh về cùng độ sâu",input:"9\n1 2\n1 3\n2 4\n2 5\n3 6\n5 7\n5 8\n6 9\n",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint n, LOG;\nvector<vector<int>> adj;\nvector<int> cha, sau;\n\nvoid bfs(int goc) {                    // cha và độ sâu của mọi đỉnh\n    cha.assign(n + 1, 0);\n    sau.assign(n + 1, -1);\n    vector<int> q;\n    q.push_back(goc);\n    cha[goc] = goc;                    // gốc lấy chính nó làm cha\n    sau[goc] = 0;\n    for (int i = 0; i < (int)q.size(); i++) {\n        int u = q[i];\n        for (int v : adj[u])\n            if (sau[v] == -1) { sau[v] = sau[u] + 1; cha[v] = u; q.push_back(v); }\n    }\n}\n\nvoid docCay() {\n    cin >> n;\n    adj.resize(n + 1);\n    for (int i = 0; i < n - 1; i++) {\n        int a, b;\n        cin >> a >> b;\n        adj[a].push_back(b);\n        adj[b].push_back(a);\n    }\n}\n\nvector<vector<int>> up;\n\nvoid dungBang() {\n    LOG = 1;\n    while ((1 << LOG) <= n) LOG++;\n    up.assign(LOG, vector<int>(n + 1));\n    for (int v = 1; v <= n; v++) up[0][v] = cha[v];\n    for (int k = 1; k < LOG; k++)\n        for (int v = 1; v <= n; v++)\n            up[k][v] = up[k - 1][up[k - 1][v]];   // 2^k = 2^(k-1) + 2^(k-1)\n}\n\nint lcaSai(int u, int v) {\n    if (u == v) return u;\n    for (int k = LOG - 1; k >= 0; k--) // SAI: chưa đưa u, v về cùng độ sâu\n        if (up[k][u] != up[k][v]) { u = up[k][u]; v = up[k][v]; }\n    return up[0][u];\n}\n\nint main() {\n    docCay();\n    bfs(1);\n    dungBang();\n    cout << lcaSai(7, 2) << \" \" << lcaSai(7, 5) << \"\\n\";   // đúng phải là 2 5\n    return 0;\n}",viz:[{type:"graph",base:1,xy:[[0.5,0],[0.25,0.33],[0.75,0.33],[0.08,0.66],[0.4,0.66],[0.75,0.66],[0.28,1],[0.52,1],[0.75,1]],adj:"adj",par:"cha",lab:"sau",cur:["u","v"]}],py:{code:"def doc_cay():\n    n = int(input())\n    adj = [[] for _ in range(n + 1)]\n    for _ in range(n - 1):\n        a, b = map(int, input().split())\n        adj[a].append(b)\n        adj[b].append(a)\n    return n, adj\n\ndef bfs(goc):                          # cha và độ sâu của mọi đỉnh\n    cha = [0] * (n + 1)\n    sau = [-1] * (n + 1)\n    cha[goc] = goc                     # gốc lấy chính nó làm cha\n    sau[goc] = 0\n    q = [goc]\n    for u in q:\n        for v in adj[u]:\n            if sau[v] == -1:\n                sau[v] = sau[u] + 1\n                cha[v] = u\n                q.append(v)\n    return cha, sau\n\ndef dung_bang():\n    LOG = n.bit_length()               # 2^LOG > n\n    up = [cha[:]]\n    for k in range(1, LOG):\n        prev = up[k - 1]\n        up.append([prev[prev[v]] for v in range(n + 1)])   # 2^k = 2^(k-1) + 2^(k-1)\n    return LOG, up\n\ndef lca_sai(u, v):\n    if u == v:\n        return u\n    for k in range(LOG - 1, -1, -1):   # SAI: chưa đưa u, v về cùng độ sâu\n        if up[k][u] != up[k][v]:\n            u = up[k][u]\n            v = up[k][v]\n    return up[0][u]\n\nn, adj = doc_cay()\ncha, sau = bfs(1)\nLOG, up = dung_bang()\nprint(lca_sai(7, 2), lca_sai(7, 5))    # đúng phải là 2 5"},cs:{code:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static int n;\n    static List<int>[] adj;\n    static int[] cha, sau;\n\n    static void DocCay()\n    {\n        n = int.Parse(Console.ReadLine());\n        adj = new List<int>[n + 1];\n        for (int i = 0; i <= n; i++) adj[i] = new List<int>();\n        for (int i = 0; i < n - 1; i++)\n        {\n            int[] e = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            adj[e[0]].Add(e[1]);\n            adj[e[1]].Add(e[0]);\n        }\n    }\n\n    static void Bfs(int goc)               // cha và độ sâu của mọi đỉnh\n    {\n        cha = new int[n + 1];\n        sau = new int[n + 1];\n        for (int i = 0; i <= n; i++) sau[i] = -1;\n        var q = new List<int> { goc };\n        cha[goc] = goc;                    // gốc lấy chính nó làm cha\n        sau[goc] = 0;\n        for (int i = 0; i < q.Count; i++)\n        {\n            int u = q[i];\n            foreach (int v in adj[u])\n                if (sau[v] == -1) { sau[v] = sau[u] + 1; cha[v] = u; q.Add(v); }\n        }\n    }\n\n    static int LOG;\n    static int[][] up;\n\n    static void DungBang()\n    {\n        LOG = 1;\n        while ((1 << LOG) <= n) LOG++;\n        up = new int[LOG][];\n        up[0] = (int[])cha.Clone();\n        for (int k = 1; k < LOG; k++)\n        {\n            up[k] = new int[n + 1];\n            for (int v = 0; v <= n; v++) up[k][v] = up[k - 1][up[k - 1][v]];   // 2^k = 2^(k-1) + 2^(k-1)\n        }\n    }\n\n    static int LcaSai(int u, int v)\n    {\n        if (u == v) return u;\n        for (int k = LOG - 1; k >= 0; k--) // SAI: chưa đưa u, v về cùng độ sâu\n            if (up[k][u] != up[k][v]) { u = up[k][u]; v = up[k][v]; }\n        return up[0][u];\n    }\n\n    static void Main()\n    {\n        DocCay();\n        Bfs(1);\n        DungBang();\n        Console.WriteLine(LcaSai(7, 2) + \" \" + LcaSai(7, 5));   // đúng phải là 2 5\n    }\n}"}}];
